private static str calculateAmount(LeaveTransactionType _leaveTransactionType)
{
    str sumAmount = SysComputedColumn::returnField(tableStr(NVLeavePlanTypeBalanceView), identifierStr(LeaveBankTransaction), fieldStr(LeaveBankTransaction, Amount));
    str transactionType = SysComputedColumn::returnField(tableStr(NVLeavePlanTypeBalanceView), identifierStr(LeaveBankTransaction), fieldStr(LeaveBankTransaction, TransactionType));
    str ifStatement = SysComputedColumn::if(SysComputedColumn::equalExpression(transactionType, SysComputedColumn::returnLiteral(_leaveTransactionType)),
        sumAmount, SysComputedColumn::returnLiteral(0));

    return SysComputedColumn::sum(ifStatement);
}

private static str carryForward()
{
    str carryForwardTransfer = NVLeavePlanTypeBalanceView::carryForwardTransfer();
    str carryForwardAdjustment = NVLeavePlanTypeBalanceView::carryForwardAdjustment();

    return SysComputedColumn::add(carryForwardTransfer, carryForwardAdjustment);
}

public static LeaveDate getBalanceCalculationEndDate(HcmWorkerRecId _workerRecId, LeavePlanRecId _planRecId)
{
    LeaveDate companyCurrentDate = HcmDateTimeUtil::companyCurrentDate();
    LeaveDate balanceCalculationEndDate;

    if (HRMParameters::find().LeaveBalanceCalculationOption == LeaveBalanceCalculationOption::AccrualPeriod)
    {
        LeaveEnrollment enrollment = LeaveEnrollment::findByWorkerPlan(_workerRecId, _planRecId);
        LeavePlan plan = LeavePlan::find(_planRecId);

        if (plan.nvHasAccrualPeriods())
        {
            NVLeaveAccrualPeriodCalculator accrualPeriodCalculator = NVLeaveAccrualPeriodCalculator::newForPlanEnrollment(
                plan,
                enrollment);

            LeaveAccrualPeriod currentAccrualPeriod = accrualPeriodCalculator.getAccrualPeriod(companyCurrentDate);

            balanceCalculationEndDate = currentAccrualPeriod.getEndDate();
        }
        else
        {
            balanceCalculationEndDate = companyCurrentDate;
        }
    }
    else
    {
        balanceCalculationEndDate = companyCurrentDate;
    }

    return balanceCalculationEndDate;
}

private static str takenBalance() { str worker = SysComputedColumn::returnField(tableStr(NVLeavePlanTypeBalanceView), identifierStr(LeaveEnrollment), fieldStr(LeaveEnrollment, Worker)); str plan = SysComputedColumn::returnField(tableStr(NVLeavePlanTypeBalanceView), identifierStr(LeaveEnrollment), fieldStr(LeaveEnrollment, Plan));
LeaveDate currentDate = HcmDateTimeUtil::companyCurrentDate(); LeaveEnrollment enrollment = LeaveEnrollment::findByWorkerPlan(str2Int64(worker), str2Int64(plan)); LeavePlan leavePlan = LeavePlan::find(str2Int64(plan));
NVLeaveAccrualPeriodCalculator calculator = NVLeaveAccrualPeriodCalculator::newForPlanEnrollment(leavePlan, enrollment); LeaveDate accrualDateBasis = calculator.getAccrualDateBasis();
LeaveDate planYearStartDate = NVLeaveAccrualPeriodUtil::getLastAccrualDateRelativeTo( currentDate, accrualDateBasis, LeavePlanAccrualFrequency::Annually);
LeaveDate balanceCalculationEndDate = NVLeavePlanTypeBalanceView::getBalanceCalculationEndDate(str2Int64(worker), str2Int64(plan));
return strFmt( @"SELECT COALESCE(SUM(-AMOUNT), 0) FROM %1 AS PROCESSEDTRANS WHERE EXISTS (SELECT * FROM %2 AS PLANTIER WHERE PROCESSEDTRANS.LEAVETYPE = PLANTIER.TYPE AND PLANTIER.PLAN_ = %3) AND PROCESSEDTRANS.WORKER = %4 AND PROCESSEDTRANS.TRANSACTIONDATE >= %6 AND (PROCESSEDTRANS.TRANSACTIONTYPE = %7 OR PROCESSEDTRANS.TRANSACTIONTYPE = %8) AND PROCESSEDTRANS.LeaveType = %9 AND PROCESSEDTRANS.PARTITION = %10", (new SysDictTable(tableNum(LeaveBankTransaction))).name(DbBackend::Sql), (new SysDictTable(tableNum(LeavePlanTier))).name(DbBackend::Sql), SysComputedColumn::returnField( viewstr(NVLeavePlanTypeBalanceView), identifierStr(LeaveEnrollment), fieldStr(LeaveEnrollment, Plan)), SysComputedColumn::returnField( viewstr(NVLeavePlanTypeBalanceView), identifierStr(LeaveEnrollment), fieldStr(LeaveEnrollment, Worker)), SysComputedColumn::returnLiteral(balanceCalculationEndDate), SysComputedColumn::returnLiteral(planYearStartDate), SysComputedColumn::returnLiteral(LeaveTransactionType::Request), SysComputedColumn::returnLiteral(LeaveTransactionType::LeaveOfAbsenceRequest), SysComputedColumn::returnField( viewstr(NVLeavePlanTypeBalanceView), identifierStr(LeaveBankTransaction), fieldStr(LeaveBankTransaction, LeaveType)), SysComputedColumn::returnField( viewstr(NVLeavePlanTypeBalanceView), identifierStr(LeaveEnrollment), fieldStr(LeaveEnrollment, Partition))); }
